mapper.select:
SELECT MAX(t.id) AS id, COUNT(1) AS bind_count FROM (
    SELECT id FROM t_bind_phone_record ORDER BY id LIMIT #{limitSize}
) t

mapper.update:
UPDATE s_user_id u
    INNER JOIN t_bind_phone_record b ON b.user_id = u.user_id AND b.id <= #{toId}
    SET u.phone = b.phone,u.bind_time = b.bind_time
